// SETTINGS: edit these two lines.
const MY_ADDRESS = 'you@gmail.com'; // your Gmail address (the agent skips its own digest emails)
const DEMO_MODE = true; // true = only the demo inbox (.example senders) goes to the AI. Set false for your
                        // own mail, and use Gemini's PAID tier for real mail (free-tier inputs may be used
                        // to improve Google's products).
// Everything waiting in the queue -> batches the model can read in one call.
const started = new Date().toISOString();
// DEMO MODE: only seeded demo senders are sent to the model (real mail stays out of the free tier)
const isDemo = s => /@[^>\s]+\.example>?\s*$/i.test(String(s || '').trim());
const mails = $input.all().filter(it => it.json.id !== undefined && (!DEMO_MODE || isDemo(it.json.sender))).map((it, i) => ({
  n: i + 1, id: it.json.id, from: it.json.sender, subject: it.json.subject, date: it.json.received, body: it.json.body,
}));
const size = 75;
const out = [];
for (let k = 0; k < mails.length; k += size) {
  const batch = mails.slice(k, k + size);
  out.push({ json: {
    batchNo: out.length + 1, started, total: mails.length, batch,
    emailsText: batch.map(m => `#${m.n} | From: ${m.from} | Subject: ${m.subject}\n${m.body}`).join('\n---\n'),
  } });
}
return out;

// Join the model's answers back to the emails, write ONE digest, and list anything that wasn't sorted.
const prep = $('Prepare batches').all().map(i => i.json);
const mails = prep.flatMap(b => b.batch);
const byN = Object.fromEntries(mails.map(m => [m.n, m]));
const answers = $input.all().flatMap(i => i.json.output?.emails || []);
const seen = new Set();
const rows = [];
for (const a of answers) {
  if (!byN[a.n] || seen.has(a.n)) continue;
  seen.add(a.n);
  rows.push({ ...byN[a.n], ...a, body: undefined });
}
const missing = mails.filter(m => !seen.has(m.n)).map(m => ({ n: m.n, id: m.id, from: m.from, subject: m.subject }));
const started = prep[0]?.started;
const finished = new Date().toISOString();
const seconds = Math.round((new Date(finished) - new Date(started)) / 1000);
const count = c => rows.filter(r => r.category === c).length;
const esc = s => String(s || '').replace(/[&<>]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]));
const rank = { high: 0, medium: 1, low: 2 };
const act = rows.filter(r => r.category === 'action_needed').sort((a, b) => rank[a.priority] - rank[b.priority]);
const pers = rows.filter(r => r.category === 'personal');
const item = r => `<tr><td style="padding:10px 0;border-top:1px solid #e3e8ef">
  <div style="font:600 14px Arial;color:#0f1b2d">${esc(r.subject)} <span style="font-weight:400;color:#5b6b80">· ${esc(r.from)}</span>
  ${r.priority === 'high' ? '<span style="background:#ffe8cc;color:#9a4a00;border-radius:4px;padding:1px 6px;font-size:11px;margin-left:6px">HIGH</span>' : ''}</div>
  <div style="font:14px Arial;color:#2b3a4f;margin-top:3px">${esc(r.summary)}</div>
  ${r.suggested_reply ? `<div style="font:13px Arial;color:#0b6b74;background:#eefafb;border-left:3px solid #13b5c4;padding:6px 10px;margin-top:6px">Suggested reply: ${esc(r.suggested_reply)}</div>` : ''}
</td></tr>`;
const chip = (label, n) => `<td style="padding:8px 12px;background:#f2f5f9;border-radius:6px;font:13px Arial;color:#2b3a4f">${label} <b>${n}</b></td><td width="6"></td>`;
const html = `<div style="max-width:640px;margin:auto;font-family:Arial">
<h2 style="font:700 22px Arial;color:#0f1b2d;margin:0 0 4px">Your inbox, sorted</h2>
<p style="font:14px Arial;color:#5b6b80;margin:0 0 14px">${rows.length} emails read in ${Math.floor(seconds / 60)} min ${seconds % 60} s · ${act.length} need you</p>
<table cellspacing="0"><tr>${chip('Needs you', act.length)}${chip('Personal', pers.length)}${chip('Receipts', count('receipt'))}${chip('Alerts', count('notification'))}${chip('Newsletters', count('newsletter'))}${chip('Promos', count('promo'))}</tr></table>
${missing.length ? `<div style="margin-top:14px;padding:10px 12px;background:#fff4e5;border-left:3px solid #f0a020;font:14px Arial;color:#6b3d00"><b>Not sorted yet (${missing.length}).</b> They stay in the queue for the next run:<br>${missing.map(m => esc(m.subject) + ' · ' + esc(m.from)).join('<br>')}</div>` : ''}
<h3 style="font:700 16px Arial;color:#0f1b2d;margin:20px 0 4px">Needs you (${act.length})</h3>
<table width="100%" cellspacing="0">${act.map(item).join('')}</table>
<h3 style="font:700 16px Arial;color:#0f1b2d;margin:20px 0 4px">Personal (${pers.length})</h3>
<table width="100%" cellspacing="0">${pers.map(item).join('')}</table>
<p style="font:12px Arial;color:#8a97a8;margin-top:20px">Receipts, alerts, newsletters and promos are counted above. Nothing was sent to anyone; suggested replies are drafts for you.</p>
</div>`;
const stamp = finished.replace(/[:.]/g, '-');
const record = { version: 2, started, finished, seconds, total: mails.length, sorted: rows.length, missing, counts: {
  action_needed: act.length, personal: pers.length, receipt: count('receipt'), notification: count('notification'),
  newsletter: count('newsletter'), promo: count('promo') }, batches: prep.length, rows };
return [{
  json: { subject: `Inbox digest · ${rows.length} emails, ${act.length} need you`, html, seconds, stamp,
          sortedIds: rows.map(r => r.id) },
  binary: { data: { data: Buffer.from(JSON.stringify(record, null, 1)).toString('base64'),
                    mimeType: 'application/json', fileName: `run-${stamp}.json`, fileExtension: 'json' } },
}];
